package com.bankpli.javabank.config;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.stereotype.Service;
@Service public class KycService {private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();public record Result(boolean valid,String profileHash){}public Result validate(String legalName,String documentId,String password){boolean valid=legalName!=null&&!legalName.isBlank()&&documentId!=null&&documentId.matches("[A-Za-z0-9-]{6,30}")&&password!=null&&password.length()>=10;return new Result(valid,valid?sha256(legalName.trim()+"|"+documentId.trim()):"");}public String hashPassword(String password){return encoder.encode(password);}private String sha256(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
